const ALL_LANGS_STR: &str = "bash, c, cpp, crystal, csharp, dart, elixir, go, groovy, haskell, java, javascript, julia, kotlin, lua, nim, perl, php, python, r, ruby, rust, swift, typescript, zig";

fn detect_language(code: &str) -> Lang {
    if code.contains("std::") || code.contains("cout <<") || code.contains("cin >>") {
        Lang::Cpp
    } else if code.contains("#include <") || code.contains("#include \"") {
        Lang::C
    } else if code.contains("package main") || code.contains("func main(") || code.contains("fmt.Println") {
        Lang::Go
    } else if code.contains("println!(") || code.contains("fn main(") || code.contains("pub fn ") {
        Lang::Rust
    } else if code.contains("public class") || code.contains("public static void main") || code.contains("System.out.") {
        Lang::Java
    } else if code.contains("using System") || code.contains("Console.WriteLine") {
        Lang::Csharp
    } else if code.contains("void main()") || code.contains("import 'package:") {
        Lang::Dart
    } else if code.contains("IO.puts") || code.contains("defmodule ") {
        Lang::Elixir
    } else if code.contains("fun main(") || code.contains("val ") {
        Lang::Kotlin
    } else if code.contains("println(") {
        Lang::Julia
    } else if code.contains("local function") || code.contains("print(") {
        Lang::Lua
    } else if code.contains("<?php") || code.contains("echo \"") {
        Lang::Php
    } else if code.contains("echo ") || code.starts_with("ls ") || code.starts_with("cat ") || code.starts_with("cd ") {
        Lang::Bash
    } else if code.contains("my $") || code.contains("use strict") || code.contains("sub ") {
        Lang::Perl
    } else if code.contains("puts ") || code.contains("require \"") {
        Lang::Ruby
    } else if code.contains("function ") || code.contains("console.log") {
        Lang::Javascript
    } else if code.contains("interface ") || code.contains("type ") {
        Lang::Typescript
    } else if code.contains("proc ") {
        Lang::Nim
    } else if code.contains("@import") || code.contains("pub fn main") {
        Lang::Zig
    } else if code.contains("library(") || code.contains("<-") {
        Lang::R
    } else if code.contains("main =") || code.contains("let ") {
        Lang::Haskell
    } else if code.contains("println ") {
        Lang::Groovy
    } else if code.contains("enum ") || code.contains("require \"crystal\"") {
        Lang::Crystal
    } else if code.contains("import Swift") || code.contains("import Foundation") {
        Lang::Swift
    } else {
        Lang::Python
    }
}

fn command_exists(cmd: &str) -> bool {
    if let Ok(path) = env::var("PATH") {
        for p in path.split(':') {
            let full_path = Path::new(p).join(cmd);
            if full_path.is_file() {
                return true;
            }
        }
    }
    false
}

fn check_tool(lang: Lang, is_file: bool) -> Result<(), String> {
    match lang {
        Lang::Bash => {
            if !command_exists("bash") {
                return Err("Error: No such file or directory (os error 2)".to_string());
            }
        }
        Lang::C => {
            if !command_exists("gcc") && !command_exists("clang") && !command_exists("cc") {
                return Err("Error: C support requires a C compiler such as `cc`, `clang`, or `gcc`. Install one and ensure it is on your PATH.".to_string());
            }
        }
        Lang::Cpp => {
            if !command_exists("g++") && !command_exists("clang++") && !command_exists("c++") {
                return Err("Error: C++ support requires a C++ compiler such as `c++`, `clang++`, or `g++`. Install one and ensure it is on your PATH.".to_string());
            }
        }
        Lang::Crystal => {
            if !command_exists("crystal") {
                return Err("Error: Crystal support requires the `crystal` executable. Install it from https://crystal-lang.org/install/ and ensure it is on your PATH.".to_string());
            }
        }
        Lang::Csharp => {
            if !command_exists("dotnet") {
                return Err("Error: C# support requires the `dotnet` CLI. Install the .NET SDK from https://dotnet.microsoft.com/download and ensure `dotnet` is on your PATH.".to_string());
            }
        }
        Lang::Dart => {
            if !command_exists("dart") {
                return Err("Error: Dart support requires the `dart` executable. Install the Dart SDK from https://dart.dev/get-dart and ensure `dart` is on your PATH.".to_string());
            }
        }
        Lang::Elixir => {
            if !command_exists("elixir") {
                return Err("Error: Elixir support requires the `elixir` executable. Install Elixir from https://elixir-lang.org/install.html and ensure `elixir` is on your PATH.".to_string());
            }
        }
        Lang::Go => {
            if !command_exists("go") {
                return Err("Error: Go support requires the `go` executable. Install it from https://go.dev/dl/ and ensure it is on your PATH.".to_string());
            }
        }
        Lang::Groovy => {
            if !command_exists("groovy") {
                return Err("Error: Groovy support requires the `groovy` executable. Install it from https://groovy-lang.org/download.html and make sure it is available on your PATH.".to_string());
            }
        }
        Lang::Haskell => {
            if !command_exists("runghc") {
                return Err("Error: Haskell support requires the `runghc` executable. Install the GHC toolchain from https://www.haskell.org/ghc/ (or via ghcup) and ensure `runghc` is on your PATH.".to_string());
            }
        }
        Lang::Java => {
            if !command_exists("javac") {
                return Err("Error: Java support requires the `javac` compiler. Install the JDK from https://adoptium.net/ or your vendor of choice and ensure it is on your PATH.".to_string());
            }
        }
        Lang::Javascript => {
            if !command_exists("node") {
                return Err("Error: No such file or directory (os error 2)".to_string());
            }
        }
        Lang::Julia => {
            if !command_exists("julia") {
                return Err("Error: Julia support requires the `julia` executable. Install Julia from https://julialang.org/downloads/ and ensure `julia` is on your PATH.".to_string());
            }
        }
        Lang::Kotlin => {
            if !command_exists("kotlinc") {
                return Err("Error: Kotlin support requires the `kotlinc` compiler. Install it from https://kotlinlang.org/docs/command-line.html and ensure it is on your PATH.".to_string());
            }
        }
        Lang::Lua => {
            if !command_exists("lua") {
                return Err("Error: Lua support requires the `lua` executable. Install it from https://www.lua.org/download.html and ensure it is on your PATH.".to_string());
            }
        }
        Lang::Nim => {
            if !command_exists("nim") {
                return Err("Error: Nim support requires the `nim` executable. Install it from https://nim-lang.org/install.html and ensure `nim` is on your PATH.".to_string());
            }
        }
        Lang::Perl => {
            if !command_exists("perl") {
                return Err("Error: Perl support requires the `perl` executable. Install Perl from https://www.perl.org/get.html and ensure `perl` is on your PATH.".to_string());
            }
        }
        Lang::Php => {
            if !command_exists("php") {
                return Err("Error: PHP support requires the `php` CLI executable. Install PHP and ensure it is on your PATH.".to_string());
            }
        }
        Lang::Python => {
            if !command_exists("python3") && !command_exists("python") {
                return Err("Error: No such file or directory (os error 2)".to_string());
            }
        }
        Lang::R => {
            if !command_exists("Rscript") {
                return Err("Error: R support requires the `Rscript` executable. Install R from https://cran.r-project.org/ and ensure `Rscript` is on your PATH.".to_string());
            }
        }
        Lang::Ruby => {
            if !command_exists("ruby") {
                return Err("Error: No such file or directory (os error 2)".to_string());
            }
        }
        Lang::Rust => {
            if !command_exists("rustc") {
                return Err("Error: Rust support requires the `rustc` executable. Install it via Rustup and ensure it is on your PATH.".to_string());
            }
        }
        Lang::Swift => {
            if !command_exists("swift") {
                return Err("Error: Swift support requires the `swift` executable. Install Xcode command-line tools or the Swift toolchain from https://www.swift.org/download/ and ensure `swift` is on your PATH.".to_string());
            }
        }
        Lang::Typescript => {
            if !command_exists("deno") {
                if is_file {
                    return Err("Error: failed to run Deno for file execution because 'deno' was not found in PATH. Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH.".to_string());
                } else {
                    return Err("Error: failed to run Deno for inline execution because 'deno' was not found in PATH. Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH.".to_string());
                }
