        Lang::Cpp => {
            if !command_exists("g++") && !command_exists("clang++") && !command_exists("c++") {
                return Err("Error: C++ support requires a C++ compiler such as `c++`, `clang++`, or `g++`. Install one and ensure it is on your PATH.".to_string());
