fn create_temp_dir(prefix: &str) -> io::Result<PathBuf> {
    let pid = std::process::id();
    let now = Instant::now().elapsed().as_nanos();
    let chars = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    let mut rand_str = String::new();
    let mut seed = (pid as u128) ^ now;
    for _ in 0..6 {
        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1);
        let idx = ((seed >> 32) as usize) % chars.len();
        rand_str.push(chars.chars().nth(idx).unwrap());
    }
    let dir_name = format!("{}-{}", prefix, rand_str);
    let tmp_path = env::temp_dir().join(dir_name);
    fs::create_dir_all(&tmp_path)?;
    Ok(tmp_path)
}

fn execute_code(lang: Lang, code: &str, is_file: bool, file_path: Option<&Path>) -> i32 {
    if let Err(msg) = check_tool(lang, is_file) {
        eprintln!("{}", msg);
        return 1;
    }

    match lang {
        Lang::Bash => {
            let mut cmd = Command::new("bash");
            if is_file {
                cmd.arg(file_path.unwrap());
            } else {
                cmd.arg("-c").arg(code);
            }
            match cmd.status() {
                Ok(st) => st.code().unwrap_or(1),
                Err(e) => {
                    eprintln!("Error: {}", e);
                    1
                }
            }
        }
        Lang::C => {
            let temp_dir = match create_temp_dir("run-c") {
                Ok(d) => d,
                Err(e) => {
                    eprintln!("Error: {}", e);
                    return 1;
                }
            };
            let c_path = temp_dir.join("main.c");
            let out_path = temp_dir.join("main");

            if is_file {
                if let Err(_) = fs::copy(file_path.unwrap(), &c_path) {
                    eprintln!("Error: failed to copy C source from {} to {}", file_path.unwrap().display(), c_path.display());
                    let _ = fs::remove_dir_all(&temp_dir);
                    return 1;
                }
            } else {
                let wrapped_code = if code.contains("main(") {
                    code.to_string()
                } else {
                    let mut indented = String::new();
                    for line in code.lines() {
                        indented.push_str("    ");
                        indented.push_str(line);
                        indented.push('\n');
                    }
                    format!("#include <stdio.h>\n\nint main(void)\n{{\n{}    return 0;\n}}\n", indented)
                };
                if let Err(e) = fs::write(&c_path, wrapped_code) {
                    eprintln!("Error: {}", e);
                    let _ = fs::remove_dir_all(&temp_dir);
                    return 1;
                }
            }

            let compiler = if command_exists("gcc") {
                "gcc"
            } else if command_exists("clang") {
                "clang"
            } else {
                "cc"
            };

            let compile_st = Command::new(compiler)
                .args([c_path.to_str().unwrap(), "-o", out_path.to_str().unwrap(), "-lm"])
                .status();

            let code_res = match compile_st {
                Ok(st) if st.success() => {
                    let run_st = Command::new(&out_path).status();
                    run_st.ok().and_then(|s| s.code()).unwrap_or(1)
                }
                Ok(st) => st.code().unwrap_or(1),
                Err(e) => {
                    eprintln!("Error: {}", e);
                    1
                }
            };

            let _ = fs::remove_dir_all(&temp_dir);
            code_res
        }
        Lang::Cpp => {
            let temp_dir = match create_temp_dir("run-cpp") {
                Ok(d) => d,
                Err(e) => {
                    eprintln!("Error: {}", e);
                    return 1;
                }
            };
            let cpp_path = temp_dir.join("main.cpp");
            let out_path = temp_dir.join("main");

            if is_file {
                if let Err(_) = fs::copy(file_path.unwrap(), &cpp_path) {
                    eprintln!("Error: failed to copy C++ source from {} to {}", file_path.unwrap().display(), cpp_path.display());
                    let _ = fs::remove_dir_all(&temp_dir);
                    return 1;
                }
            } else {
                if let Err(e) = fs::write(&cpp_path, code) {
                    eprintln!("Error: {}", e);
                    let _ = fs::remove_dir_all(&temp_dir);
                    return 1;
                }
            }

            let compiler = if command_exists("g++") {
                "g++"
            } else if command_exists("clang++") {
                "clang++"
            } else {
                "c++"
            };

            let compile_st = Command::new(compiler)
                .args(["-std=c++17", cpp_path.to_str().unwrap(), "-o", out_path.to_str().unwrap()])
                .status();

            let code_res = match compile_st {
                Ok(st) if st.success() => {
                    let run_st = Command::new(&out_path).status();
                    run_st.ok().and_then(|s| s.code()).unwrap_or(1)
                }
                Ok(st) => st.code().unwrap_or(1),
                Err(e) => {
                    eprintln!("Error: {}", e);
                    1
                }
            };

            let _ = fs::remove_dir_all(&temp_dir);
            code_res
        }
        Lang::Go => {
            if is_file {
                let st = Command::new("go").arg("run").arg(file_path.unwrap()).status();
                match st {
                    Ok(s) => s.code().unwrap_or(1),
                    Err(_) => {
                        eprintln!("Error: failed to invoke /usr/local/go/bin/go to run {}", file_path.unwrap().display());
                        1
                    }
                }
            } else {
                let temp_dir = match create_temp_dir("run-go") {
                    Ok(d) => d,
                    Err(e) => {
                        eprintln!("Error: {}", e);
                        return 1;
                    }
                };
                let go_path = temp_dir.join("main.go");
                if let Err(e) = fs::write(&go_path, code) {
                    eprintln!("Error: {}", e);
                    let _ = fs::remove_dir_all(&temp_dir);
                    return 1;
                }
                let st = Command::new("go").arg("run").arg(&go_path).status();
                let res = st.ok().and_then(|s| s.code()).unwrap_or(1);
                let _ = fs::remove_dir_all(&temp_dir);
                res
            }
        }
        Lang::Perl => {
            let mut cmd = Command::new("perl");
            if is_file {
                cmd.arg(file_path.unwrap());
            } else {
                cmd.arg("-e").arg(code);
            }
            match cmd.status() {
                Ok(st) => st.code().unwrap_or(1),
                Err(_) => {
                    if is_file {
                        eprintln!("Error: failed to execute /usr/bin/perl with script {}", file_path.unwrap().display());
                    } else {
                        eprintln!("Error: No such file or directory (os error 2)");
                    }
                    1
                }
            }
        }
        Lang::Python => {
            let py_bin = if command_exists("python3") { "python3" } else { "python" };
            let mut cmd = Command::new(py_bin);
            if is_file {
                cmd.arg(file_path.unwrap());
            } else {
                cmd.arg("-c").arg(code);
            }
            match cmd.status() {
                Ok(st) => st.code().unwrap_or(1),
                Err(e) => {
                    eprintln!("Error: {}", e);
                    1
                }
            }
        }
        Lang::Ruby => {
            let mut cmd = Command::new("ruby");
            if is_file {
                cmd.arg(file_path.unwrap());
            } else {
                cmd.arg("-e").arg(code);
            }
            match cmd.status() {
                Ok(st) => st.code().unwrap_or(1),
                Err(e) => {
                    eprintln!("Error: {}", e);
                    1
                }
            }
        }
        Lang::Javascript => {
            let mut cmd = Command::new("node");
            if is_file {
                cmd.arg(file_path.unwrap());
            } else {
                cmd.arg("-e").arg(code);
            }
            match cmd.status() {
                Ok(st) => st.code().unwrap_or(1),
                Err(e) => {
                    eprintln!("Error: {}", e);
                    1
                }
            }
        }
        Lang::Rust => {
            let temp_dir = match create_temp_dir("run-rust") {
                Ok(d) => d,
                Err(e) => {
                    eprintln!("Error: {}", e);
                    return 1;
                }
            };
            let rs_path = temp_dir.join("main.rs");
            let out_path = temp_dir.join("main");

            if is_file {
                if let Err(_) = fs::copy(file_path.unwrap(), &rs_path) {
                    let st = Command::new("rustc").arg(file_path.unwrap()).status();
                    let res = st.ok().and_then(|s| s.code()).unwrap_or(1);
                    let _ = fs::remove_dir_all(&temp_dir);
                    return res;
                }
            } else {
                if let Err(e) = fs::write(&rs_path, code) {
                    eprintln!("Error: {}", e);
                    let _ = fs::remove_dir_all(&temp_dir);
                    return 1;
                }
            }

            let compile_st = Command::new("rustc")
                .args(["--crate-name", "run_snippet", rs_path.to_str().unwrap(), "-o", out_path.to_str().unwrap()])
                .status();

            let code_res = match compile_st {
                Ok(st) if st.success() => {
                    let run_st = Command::new(&out_path).status();
                    run_st.ok().and_then(|s| s.code()).unwrap_or(1)
                }
                Ok(st) => st.code().unwrap_or(1),
                Err(e) => {
                    eprintln!("Error: {}", e);
                    1
                }
            };

            let _ = fs::remove_dir_all(&temp_dir);
            code_res
        }
        _ => {
            eprintln!("Error: Language execution for {:?} is not installed on this system.", lang);
            1
        }
    }
}

