fn detect_language(code: &str) -> Lang {
    if code.contains("std::") || code.contains("cout <<") || code.contains("cin >>") {
        Lang::Cpp
    } else if code.contains("#include <") || code.contains("#include \"") {
        Lang::C
    } else if code.contains("package main") || code.contains("func main(") || code.contains("fmt.Println") {
        Lang::Go
    } else if code.contains("println!(") || code.contains("fn main(") || code.contains("pub fn ") {
        Lang::Rust
    } else if code.contains("public class") || code.contains("public static void main") || code.contains("System.out.") {
        Lang::Java
    } else if code.contains("using System") || code.contains("Console.WriteLine") {
        Lang::Csharp
    } else if code.contains("void main()") || code.contains("import 'package:") {
        Lang::Dart
    } else if code.contains("IO.puts") || code.contains("defmodule ") {
        Lang::Elixir
    } else if code.contains("fun main(") || code.contains("val ") {
        Lang::Kotlin
    } else if code.contains("println(") {
        Lang::Julia
    } else if code.contains("local function") || code.contains("print(") {
        Lang::Lua
    } else if code.contains("<?php") || code.contains("echo \"") {
        Lang::Php
    } else if code.contains("echo ") || code.starts_with("ls ") || code.starts_with("cat ") || code.starts_with("cd ") {
        Lang::Bash
    } else if code.contains("my $") || code.contains("use strict") || code.contains("sub ") {
        Lang::Perl
    } else if code.contains("puts ") || code.contains("require \"") {
        Lang::Ruby
    } else if code.contains("function ") || code.contains("console.log") {
        Lang::Javascript
    } else if code.contains("interface ") || code.contains("type ") {
        Lang::Typescript
    } else if code.contains("proc ") {
        Lang::Nim
    } else if code.contains("@import") || code.contains("pub fn main") {
        Lang::Zig
    } else if code.contains("library(") || code.contains("<-") {
        Lang::R
    } else if code.contains("main =") || code.contains("let ") {
        Lang::Haskell
    } else if code.contains("println ") {
        Lang::Groovy
    } else if code.contains("enum ") || code.contains("require \"crystal\"") {
        Lang::Crystal
    } else if code.contains("import Swift") || code.contains("import Foundation") {
        Lang::Swift
    } else {
        Lang::Python
    }
}

fn command_exists(cmd: &str) -> bool {
    if let Ok(path) = env::var("PATH") {
        for p in path.split(':') {
            let full_path = Path::new(p).join(cmd);
            if full_path.is_file() {
                return true;
            }
        }
    }
    false
}

