fn print_help(binary_name: &str) {
    println!("Universal multi-language runner and REPL");
    println!();
    println!("Usage: {} [OPTIONS] [ARGS]...", binary_name);
    println!();
    println!("Arguments:");
    println!("  [ARGS]...  Positional arguments (language, code, or file)");
    println!();
    println!("Options:");
    println!("  -V, --version      Print version information and exit");
    println!("  -l, --lang <LANG>  Explicitly choose the language to execute");
    println!("  -f, --file <PATH>  Execute code from the provided file path");
    println!("  -c, --code <CODE>  Execute the provided code snippet");
    println!("      --no-detect    Disable heuristic language detection");
    println!("  -h, --help         Print help");
}

fn print_unknown_arg_error(binary_name: &str, arg: &str) {
    eprintln!("error: unexpected argument '{}' found", arg);
    eprintln!();
    eprintln!("  tip: to pass '{}' as a value, use '-- {}'", arg, arg);
    eprintln!();
    eprintln!("Usage: {} [OPTIONS] [ARGS]...", binary_name);
    eprintln!();
    eprintln!("For more information, try '--help'.");
}

fn print_missing_val_error(opt_name: &str, value_name: &str) {
    eprintln!("error: a value is required for '{} <{}>' but none was supplied", opt_name, value_name);
    eprintln!();
    eprintln!("For more information, try '--help'.");
}

fn run_repl(mut active_lang: Lang, mut auto_detect: bool) -> i32 {
    println!("run universal REPL. Type :help for commands.");

    let stdin = io::stdin();
    let mut stdout = io::stdout();

    // Map of session buffers / temp files for REPL
    let mut repl_sessions: std::collections::HashMap<Lang, (PathBuf, String)> = std::collections::HashMap::new();

    loop {
        print!("{}>>> ", active_lang.canonical_id());
        let _ = stdout.flush();

        let mut line = String::new();
        match stdin.read_line(&mut line) {
            Ok(0) => break, // EOF
            Ok(_) => {}
            Err(_) => break,
        }

        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        if trimmed.starts_with(':') {
            let parts: Vec<&str> = trimmed.split_whitespace().collect();
            let cmd = parts[0];
            match cmd {
                ":help" => {
                    println!("Commands:");
                    println!("  :help                 Show this help message");
                    println!("  :languages            List available languages");
                    println!("  :lang <id>            Switch to language <id>");
                    println!("  :detect on|off        Enable or disable auto language detection");
                    println!("  :reset                Reset the current language session");
                    println!("  :load <path>          Execute a file in the current language");
                    println!("  :exit, :quit          Leave the REPL");
                    println!("Any language id or alias works as a shortcut, e.g. :py, :cpp, :csharp, :php.");
                }
                ":languages" => {
                    println!("available languages: {}", ALL_LANGS_STR);
                }
                ":lang" => {
                    if parts.len() < 2 {
                        println!("usage: :lang <id>");
                    } else {
                        let target = parts[1];
                        if let Some(l) = Lang::from_str(target) {
                            if l == active_lang {
                                println!("already using {}", l.canonical_id());
                            } else {
                                active_lang = l;
                                println!("switched to {}", l.canonical_id());
                            }
                        } else {
                            println!("Error: language '{}' not supported. Available: {}", target, ALL_LANGS_STR);
                        }
                    }
                }
                ":detect" => {
                    if parts.len() < 2 {
                        println!("usage: :detect <on|off|toggle>");
                    } else {
                        match parts[1] {
                            "on" => {
                                auto_detect = true;
                                println!("auto-detect enabled");
                            }
                            "off" => {
                                auto_detect = false;
                                println!("auto-detect disabled");
                            }
                            "toggle" => {
                                auto_detect = !auto_detect;
                                if auto_detect {
                                    println!("auto-detect enabled");
                                } else {
                                    println!("auto-detect disabled");
                                }
                            }
                            _ => {
                                println!("usage: :detect <on|off|toggle>");
                            }
                        }
                    }
                }
                ":reset" => {
                    if let Some((_, buf)) = repl_sessions.get_mut(&active_lang) {
                        buf.clear();
                    }
                    println!("session for '{}' reset", active_lang.canonical_id());
                }
                ":load" => {
                    if parts.len() < 2 {
                        println!("usage: :load <path>");
                    } else {
                        let path_str = parts[1];
                        let path = Path::new(path_str);
                        let start_time = Instant::now();
                        let rc = execute_code(active_lang, "", true, Some(path));
                        let elapsed = start_time.elapsed().as_millis();
                        if rc != 0 {
                            println!("[exit code {}] ({}ms)", rc, elapsed);
                        }
                    }
                }
                ":exit" | ":quit" => {
                    break;
                }
                _ => {
                    // Check if command is a shortcut like :py, :sh, :rust, etc.
                    let shortcut = &cmd[1..];
                    if let Some(l) = Lang::from_str(shortcut) {
                        if l == active_lang {
                            println!("already using {}", l.canonical_id());
                        } else {
                            active_lang = l;
                            println!("switched to {}", l.canonical_id());
                        }
                    } else {
                        println!("unknown command: {}. Type :help for help.", cmd);
                    }
                }
            }
            continue;
        }

        // Non-colon line
        if auto_detect {
            let detected = detect_language(trimmed);
            if detected != active_lang {
                println!("[auto-detect] switching {} → {}", active_lang.canonical_id(), detected.canonical_id());
                active_lang = detected;
            }
        }

        // Ensure session entry exists
        if !repl_sessions.contains_key(&active_lang) {
            let prefix = format!("run-{}-repl", active_lang.canonical_id());
            if let Ok(dir) = create_temp_dir(&prefix) {
                let file_path = dir.join(format!("session.{}", active_lang.primary_ext()));
                repl_sessions.insert(active_lang, (file_path, String::new()));
            }
        }

        if let Some((session_file, session_buf)) = repl_sessions.get_mut(&active_lang) {
            let old_len = session_buf.len();
            session_buf.push_str(&line);

            if let Err(e) = fs::write(&*session_file, session_buf.as_bytes()) {
                eprintln!("Error writing session file: {}", e);
                session_buf.truncate(old_len);
                continue;
            }

            let start_time = Instant::now();
            let rc = execute_code(active_lang, session_buf, true, Some(session_file));
            let elapsed = start_time.elapsed().as_millis();

            if rc != 0 {
                println!("[exit code {}] ({}ms)", rc, elapsed);
                session_buf.truncate(old_len);
                let _ = fs::write(&*session_file, session_buf.as_bytes());
            }
        }
    }

    0
}

fn main() {
    let raw_args: Vec<String> = env::args().collect();
    let binary_name = Path::new(&raw_args[0])
        .file_name()
        .and_then(|s| s.to_str())
        .unwrap_or("executable");

    let mut opt_lang: Option<String> = None;
    let mut opt_file: Option<PathBuf> = None;
    let mut opt_code: Option<String> = None;
    let mut no_detect = false;
    let mut pos_args: Vec<String> = Vec::new();

    let mut i = 1;
    while i < raw_args.len() {
        let arg = &raw_args[i];
        if arg == "-h" || arg == "--help" {
            print_help(binary_name);
            std::process::exit(0);
        } else if arg == "-V" || arg == "--version" {
            print_version();
            std::process::exit(0);
        } else if arg == "--no-detect" {
            no_detect = true;
        } else if arg == "-l" || arg == "--lang" {
            if i + 1 < raw_args.len() {
                opt_lang = Some(raw_args[i + 1].clone());
                i += 1;
            } else {
                print_missing_val_error(arg, "LANG");
                std::process::exit(2);
            }
        } else if arg.starts_with("--lang=") {
            opt_lang = Some(arg["--lang=".len()..].to_string());
        } else if arg == "-f" || arg == "--file" {
            if i + 1 < raw_args.len() {
                opt_file = Some(PathBuf::from(&raw_args[i + 1]));
                i += 1;
            } else {
                print_missing_val_error(arg, "PATH");
                std::process::exit(2);
            }
        } else if arg.starts_with("--file=") {
            opt_file = Some(PathBuf::from(&arg["--file=".len()..]));
        } else if arg == "-c" || arg == "--code" {
            if i + 1 < raw_args.len() {
                opt_code = Some(raw_args[i + 1].clone());
                i += 1;
            } else {
                print_missing_val_error(arg, "CODE");
                std::process::exit(2);
            }
        } else if arg.starts_with("--code=") {
            opt_code = Some(arg["--code=".len()..].to_string());
        } else if arg.starts_with('-') && arg != "-" {
            print_unknown_arg_error(binary_name, arg);
            std::process::exit(2);
        } else {
            pos_args.push(arg.clone());
        }
        i += 1;
    }

    // Validation
    if opt_code.is_some() && opt_file.is_some() {
        eprintln!("Error: --code/--inline cannot be combined with --file");
        std::process::exit(1);
    }

    if opt_code.is_some() && !pos_args.is_empty() {
        eprintln!("Error: Unexpected positional arguments after specifying --code");
        std::process::exit(1);
    }

    if opt_file.is_some() && !pos_args.is_empty() {
        eprintln!("Error: Unexpected positional arguments when --file is present");
        std::process::exit(1);
    }

    // Parse language flag if present
    let lang_from_flag = if let Some(ref l_str) = opt_lang {
        if let Some(l) = Lang::from_str(l_str) {
            Some(l)
        } else {
            eprintln!("Error: Unknown language '{}'. Available languages: {}", l_str, ALL_LANGS_STR);
            std::process::exit(1);
        }
    } else {
        None
    };

    let is_terminal = io::stdin().is_terminal();

    // Case 1: explicit -c code
    if let Some(code) = opt_code {
        let lang = lang_from_flag.unwrap_or_else(|| {
            if no_detect {
                Lang::Python
            } else {
                detect_language(&code)
            }
        });
        let rc = execute_code(lang, &code, false, None);
        std::process::exit(rc);
    }

    // Case 2: explicit -f file
    if let Some(file_path) = opt_file {
        let lang = lang_from_flag.unwrap_or_else(|| {
            if no_detect {
                Lang::Python
            } else if let Some(ext) = file_path.extension().and_then(|s| s.to_str()) {
                Lang::from_ext(ext).unwrap_or(Lang::Python)
            } else {
                Lang::Python
            }
        });
        let rc = execute_code(lang, "", true, Some(&file_path));
        std::process::exit(rc);
    }

    // Case 3: positional arguments provided
    if !pos_args.is_empty() {
        let first_arg_lang = Lang::from_str(&pos_args[0]);

        if let Some(p_lang) = first_arg_lang {
            let target_lang = lang_from_flag.unwrap_or(p_lang);
            if pos_args.len() == 1 {
                if !is_terminal {
                    // Pipe stdin into language
                    let mut stdin_str = String::new();
                    let _ = io::stdin().read_to_string(&mut stdin_str);
                    let rc = execute_code(target_lang, &stdin_str, false, None);
                    std::process::exit(rc);
                } else {
                    let rc = run_repl(target_lang, !no_detect);
                    std::process::exit(rc);
                }
            } else if pos_args.len() == 2 && Path::new(&pos_args[1]).exists() {
                let file_path = PathBuf::from(&pos_args[1]);
                let rc = execute_code(target_lang, "", true, Some(&file_path));
                std::process::exit(rc);
            } else {
                let code_snippet = pos_args[1..].join(" ");
                let rc = execute_code(target_lang, &code_snippet, false, None);
                std::process::exit(rc);
            }
        } else {
            // first positional arg is NOT a language name
            if pos_args.len() == 1 && Path::new(&pos_args[0]).exists() {
                let file_path = PathBuf::from(&pos_args[0]);
                let target_lang = lang_from_flag.unwrap_or_else(|| {
                    if no_detect {
                        Lang::Python
                    } else if let Some(ext) = file_path.extension().and_then(|s| s.to_str()) {
                        Lang::from_ext(ext).unwrap_or(Lang::Python)
                    } else {
                        Lang::Python
                    }
                });
                let rc = execute_code(target_lang, "", true, Some(&file_path));
                std::process::exit(rc);
            } else {
                let code_snippet = pos_args.join(" ");
                let target_lang = lang_from_flag.unwrap_or_else(|| {
                    if no_detect {
                        Lang::Python
                    } else {
                        detect_language(&code_snippet)
                    }
                });
                let rc = execute_code(target_lang, &code_snippet, false, None);
                std::process::exit(rc);
            }
        }
    }

    // Case 4: No positional arguments, no -c, no -f
    if let Some(target_lang) = lang_from_flag {
        if !is_terminal {
            let mut stdin_str = String::new();
            let _ = io::stdin().read_to_string(&mut stdin_str);
            let rc = execute_code(target_lang, &stdin_str, false, None);
            std::process::exit(rc);
        } else {
            let rc = run_repl(target_lang, !no_detect);
            std::process::exit(rc);
        }
    } else {
        if !is_terminal {
            let mut stdin_str = String::new();
            let _ = io::stdin().read_to_string(&mut stdin_str);
            let target_lang = if no_detect || stdin_str.is_empty() {
                Lang::Python
            } else {
                detect_language(&stdin_str)
            };
            let rc = execute_code(target_lang, &stdin_str, false, None);
            std::process::exit(rc);
        } else {
            let rc = run_repl(Lang::Python, !no_detect);
            std::process::exit(rc);
        }
    }
}
